INSERT INTO [dbo].[seminars] ([seminar_id], [TitleHtml], [EventDetailsHtml], [Description], [StartDate], [Enddate], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Email], [Phone], [Fax], [ContactEmail], [ContactPhone], [ContactWebsite], [IsActive]) VALUES (3, N'Advanced Regression Analysis', N'<p>This workshop provides reporting basics for accounting employees new to unclaimed property or anyone who would like to refresh their knowledge of this specialized area. Topics include:</p>  <ul style="list-style-type:disc;margin-left:20px;"><li>History of unclaimed property</li><li>Purpose and benefits of the Act</li><li>Common property types</li><li>Dormancy periods</li><li>Due diligence requirements and tips</li><li>Preparing your report &ndash; when, where, and how</li><li>Common reporting and remitting errors</li><li>Electronic reporting</li><li>Developing an effective unclaimed property accounting system</li></ul>', N'This  workshop provides reporting basics for accounting employees new to unclaimed property or anyone who would like to refresh their knowledge of this specialized area.', N'2015-06-06 00:00:00', N'2015-06-08 00:00:00', N'west side', NULL, N'chicago', N'IL', NULL, N'United States', N'test@anc.com', NULL, NULL, NULL, NULL, NULL, 1)
INSERT INTO [dbo].[seminars] ([seminar_id], [TitleHtml], [EventDetailsHtml], [Description], [StartDate], [Enddate], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Email], [Phone], [Fax], [ContactEmail], [ContactPhone], [ContactWebsite], [IsActive]) VALUES (5, N'Unclaimed Property for Financial Institutions', N'<p>This free workshop covers subjects of interest to the  banking community such as:</p> <ul style="list-style-type:disc;margin-left:20px;"><li>Property types and issues unique to financial  institutions</li><li>Aging and controlling inactive customer accounts</li><li>Inactivity charges and ceasing interest</li><li>Time Certificates, IRAs, Keoghs and Special  Designation Accounts</li>      <li>Positive owner contact and notifying owners of  account changes</li><li>Abandoned safe deposit boxes</li><li>Audit process</li></ul><p><strong>Important:&nbsp; We will not cover basic reporting information  in this workshop.&nbsp; Sign up for a Basics  101 workshop if you need this information.</strong></p>', N'This free workshop covers subjects of interest to the  banking community', N'2015-06-15 00:00:00', N'2015-06-18 00:00:00', N'Streat 1', NULL, NULL, N'IL', NULL, N'United States', N'test@mmmm.com', NULL, NULL, NULL, NULL, NULL, 1)
